#!/bin/sh
set -eu
if [ "$#" -ne 1 ] || [ ! -d "$1" ]; then
  echo "Usage: ROLLBACK.sh TARGET_COPY_ROOT" >&2
  exit 2
fi
python3 - "$1" <<'PYROLLBACK'
from pathlib import Path
import base64,json,sys
root=Path(sys.argv[1]).resolve()
records=json.loads('{"employee-web/src/api/types.ts": {"bytes": "", "mode": 420}, "employee-web/src/api/employee.ts": {"bytes": "", "mode": 420}, "employee-web/src/api/employee.test.ts": {"bytes": "", "mode": 420}, "employee-web/src/composables/useWorkbenchState.ts": {"bytes": "", "mode": 420}, "employee-web/src/composables/useWorkbenchState.test.ts": {"bytes": "", "mode": 420}, "employee-web/src/utils/employee-format.ts": {"bytes": "", "mode": 420}, "employee-web/src/utils/employee-format.test.ts": {"bytes": "", "mode": 420}, "admin-web/src/utils/format.ts": {"bytes": "", "mode": 420}, "admin-web/src/utils/format.test.ts": null}')
for name,record in records.items():
 path=root/name
 if record is None:
  path.unlink(missing_ok=True)
 else:
  path.parent.mkdir(parents=True,exist_ok=True)
  path.write_bytes(base64.b64decode(record['bytes']))
  path.chmod(record['mode'])
print('ROLLBACK restored '+str(sum(value is not None for value in records.values()))+' baseline files; removed '+str(sum(value is None for value in records.values()))+' added files')
PYROLLBACK
